<script>
document.addEventListener('DOMContentLoaded', () => {
    if (typeof window.Chart !== 'function') { document.getElementById('he-chart-status').hidden = false; return; }
    const data = @json($chartData);
    const pesos = value => '₱' + Number(value).toLocaleString('en-PH', {maximumFractionDigits: 2});
    const compact = value => Math.abs(value) >= 1000000 ? '₱' + (value / 1000000).toFixed(1) + 'm' : Math.abs(value) >= 1000 ? '₱' + (value / 1000).toFixed(0) + 'k' : pesos(value);
    const labels = data.trend.map(point => point.period);
    const base = {responsive: true, maintainAspectRatio: false, animation: false, plugins: {legend: {position: 'bottom', labels: {usePointStyle: true, boxWidth: 7, padding: 18, font: {size: 10}}}}, scales: {x: {grid: {display: false}, ticks: {font: {size: 10}, maxTicksLimit: 8}}, y: {beginAtZero: true, grid: {color: '#eef2ee'}, border: {display: false}, ticks: {font: {size: 9}}}}};
    new window.Chart(document.getElementById('he-cashflow'), {type: 'bar', data: {labels, datasets: [{label: 'Issued billing', data: data.trend.map(p => p.billing / 100), backgroundColor: '#b9cfbc', borderRadius: 4, maxBarThickness: 30}, {label: 'Collections received', data: data.trend.map(p => p.collections / 100), backgroundColor: '#236f51', borderRadius: 4, maxBarThickness: 30}]}, options: {...base, plugins: {...base.plugins, tooltip: {callbacks: {label: context => context.dataset.label + ': ' + pesos(context.parsed.y)}}}, scales: {...base.scales, y: {...base.scales.y, ticks: {callback: compact, font: {size: 9}}}}}});
    const empty = data.totalUnits === 0;
    const center = {id: 'haruhayOccupancyCenter', afterDraw(chart) { const area = chart.chartArea; if (!area) return; const {ctx} = chart, x = (area.left + area.right) / 2, y = (area.top + area.bottom) / 2; ctx.save(); ctx.textAlign = 'center'; ctx.fillStyle = '#194d36'; ctx.font = 'bold 25px sans-serif'; ctx.fillText(empty ? 'N/A' : data.occupancyRate.toFixed(1) + '%', x, y); ctx.font = '10px sans-serif'; ctx.fillStyle = '#859589'; ctx.fillText('ROOM OCCUPANCY', x, y + 20); ctx.restore(); }};
    new window.Chart(document.getElementById('he-occupancy'), {type: 'doughnut', plugins: [center], data: {labels: empty ? ['No rooms recorded'] : Object.keys(data.units), datasets: [{data: empty ? [1] : Object.values(data.units), backgroundColor: empty ? ['#e5ebe6'] : ['#236f51', '#d8e2dc', '#e1b64a'], borderWidth: 3, borderColor: '#fff', hoverOffset: 4}]}, options: {responsive: true, maintainAspectRatio: false, animation: false, cutout: '78%', plugins: {legend: {display: false}, tooltip: {enabled: !empty, callbacks: {label: context => context.label + ': ' + context.parsed + ' rooms'}}}}});
    new window.Chart(document.getElementById('he-performance'), {type: 'line', data: {labels, datasets: [{label: 'Collection rate', data: data.trend.map(p => p.rate), borderColor: '#2a7856', backgroundColor: 'rgba(42,120,86,.08)', fill: true, tension: .3, pointRadius: 3, pointBackgroundColor: '#2a7856', borderWidth: 2}]}, options: {...base, plugins: {legend: {display: false}, tooltip: {callbacks: {label: context => context.parsed.y.toFixed(1) + '% of issued billing paid'}}}, scales: {...base.scales, y: {...base.scales.y, min: 0, max: 100, ticks: {callback: value => value + '%', font: {size: 9}}}}}});
    new window.Chart(document.getElementById('he-aging'), {type: 'bar', data: {labels: Object.keys(data.aging), datasets: [{label: 'Outstanding', data: Object.values(data.aging).map(value => value / 100), backgroundColor: ['#bccdbd', '#dec770', '#d4a25a', '#c47f57', '#ad5c49'], borderRadius: 4, maxBarThickness: 21}]}, options: {...base, indexAxis: 'y', plugins: {legend: {display: false}, tooltip: {callbacks: {label: context => pesos(context.parsed.x)}}}, scales: {x: {beginAtZero: true, grid: {color: '#eef2ee'}, border: {display: false}, ticks: {callback: compact, font: {size: 9}}}, y: {grid: {display: false}, ticks: {font: {size: 10}}}}}});
});
</script>
@endpush
